    // SHA-256: 5a94294b0cd545f0d1e8ba71825ea8411a8e0acbadf8def07d691bff66354c36
    private const string Woff2Base64 =
        "";

    // MDN interactive examples T-Rex roar (CC0).
    // SHA-256: 41191d0727073bf848bcc8f0bd851d71a0b0058e901abb1c1b236ad327bda52e
    private const string Mp3Base64 =
        "";

    public static byte[] Png { get; } = CreatePng();

    public const string Svg =
        """<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24"><circle cx="12" cy="12" r="10" fill="#2d7d46"/><path d="M7 12h10M12 7v10" stroke="white" stroke-width="2"/></svg>""";

    public static byte[] Woff2 { get; } = Convert.FromBase64String(Woff2Base64);

    public static byte[] Ttf { get; } = LoadSystemTrueTypeFont();

    public static byte[] Wav { get; } = CreateWave();

    public static byte[] Mp3 { get; } = Convert.FromBase64String(Mp3Base64);

    public const string Script =
